from taf.ul.kpi_selector.operations.reset_rf.classical_reset_rf.reset_rf_prototype import ResetRf


class ResetRf22R1(ResetRf):
    def get_kpi(self):
        """
        Gets kpi for reset rf operation.
        :return: dictionary with timeout, requirement and operation description for reset rf
        :rtype: dict
        """
        if any(
                [
                    all(
                        [
                            self.check_smod_bbmod_types(smod_type="ASIK", bbmod_types=["ABIL"]),
                            self.bts.number_of_smods == 1,
                            self.bts.number_of_bbmods <= 2,
                            self.bts.number_of_rmods <= 6,
                            self.bts.cell_technologies == "FDD",
                            self.bts.setup_mode == "NSA+SA",
                            self.bts.number_of_nr_cells <= 6,
                            not self.bts.is_multi_rat,
                        ],
                    ),
                    all(
                        [
                            self.check_smod_bbmod_types(smod_type="ASIK", bbmod_types=["ABIL"]),
                            self.bts.number_of_smods == 1,
                            self.bts.number_of_bbmods <= 3,
                            self.bts.number_of_rmods <= 3,
                            self.bts.cell_technologies == "TDD",
                            self.bts.setup_mode == "NSA",
                            self.bts.number_of_nr_cells <= 24,
                            not self.bts.is_multi_rat,
                        ],
                    ),
                    all(
                        [
                            self.check_smod_bbmod_types(smod_type="ASIK", bbmod_types=["ABIL"]),
                            self.bts.number_of_smods == 1,
                            self.bts.number_of_bbmods == 1,
                            self.bts.number_of_rmods <= 3,
                            self.bts.cell_technologies == "FDD",
                            self.bts.setup_mode == "NSA",
                            self.bts.number_of_nr_cells <= 3,
                            not self.bts.is_multi_rat,
                        ],
                    ),
                    all(
                        [
                            self.check_smod_bbmod_types(smod_type="ASIB", bbmod_types=["ABIL"]),
                            self.bts.number_of_smods == 1,
                            self.bts.number_of_bbmods <= 3,
                            self.bts.number_of_rmods <= 3,
                            self.bts.cell_technologies == "TDD",
                        ],
                    ),
                    all(
                        [
                            self.check_smod_bbmod_types(smod_type="ASIB", bbmod_types=["ABIO"]),
                            self.bts.number_of_smods == 1,
                            self.bts.number_of_bbmods <= 3,
                            self.bts.number_of_rmods <= 18,
                            self.bts.number_of_nr_cells <= 18,
                            self.bts.cell_technologies == "FDD",
                            not self.bts.is_multi_rat,
                        ],
                    ),
                    all(
                        [
                            self.check_smod_bbmod_types(smod_type="ASIL", bbmod_types=["ABIO"]),
                            self.bts.number_of_smods == 1,
                            self.bts.number_of_bbmods <= 3,
                            self.bts.number_of_rmods <= 2,
                            self.bts.number_of_nr_cells <= 18,
                            self.bts.cell_technologies == "TDD",
                            not self.bts.is_multi_rat,
                        ],
                    ),
                    all(
                        [
                            self.check_smod_bbmod_types(smod_type="ASIK", bbmod_types=["ABIL"]),
                            self.bts.number_of_smods == 2,
                            self.bts.number_of_bbmods <= 6,
                            self.bts.number_of_rmods <= 2,
                            self.bts.number_of_nr_cells <= 9,
                            self.bts.cell_technologies == "MIX",
                            not self.bts.is_multi_rat,
                        ],
                    ),
                    all(
                        [
                            self.check_smod_bbmod_types(smod_type="ASIL", bbmod_types=["ABIO"]),
                            self.bts.number_of_smods == 2,
                            self.bts.number_of_bbmods <= 6,
                            self.bts.number_of_rmods <= 2,
                            self.bts.cell_technologies == "TDD",
                            self.bts.number_of_nr_cells <= 6,
                            not self.bts.is_multi_rat,
                        ],
                    ),
                    all(
                        [
                            self.check_smod_bbmod_types(smod_type="ASIB", bbmod_types=["ABIO"]),
                            self.bts.number_of_smods == 1,
                            self.bts.number_of_bbmods == 1,
                            self.bts.number_of_rmods <= 6,
                            self.bts.cell_technologies == "FDD",
                            self.bts.number_of_nr_cells <= 6,
                            self.bts.setup_mode == "SA",
                            not self.bts.is_multi_rat,
                        ],
                    ),
                    all(
                        [
                            self.check_smod_bbmod_types(smod_type="ASIB", bbmod_types=["ABIO"]),
                            self.bts.number_of_smods == 1,
                            self.bts.number_of_bbmods <= 3,
                            self.bts.number_of_rmods <= 6,
                            self.bts.cell_technologies == "TDD",
                            self.bts.number_of_nr_cells <= 6,
                            self.bts.setup_mode == "NSA",
                            not self.bts.is_multi_rat,
                        ],
                    ),
                    all(
                        [
                            self.check_smod_bbmod_types(smod_type="ASIB", bbmod_types=["ABIO"]),
                            self.bts.number_of_smods == 1,
                            self.bts.number_of_bbmods <= 2,
                            self.bts.number_of_rmods <= 6,
                            self.bts.cell_technologies == "TDD",
                            self.bts.number_of_nr_cells <= 12,
                            self.bts.setup_mode == "SA",
                            not self.bts.is_multi_rat,
                        ],
                    ),
                    all(
                        [
                            "ASOE" in self.bts.smod_hw_types,
                            self.bts.number_of_smods == 1,
                            self.bts.number_of_rmods == 1,
                            self.bts.cell_technologies == "TDD",
                            self.bts.number_of_nr_cells <= 3,
                            self.bts.setup_mode == "NSA+SA",
                            not self.bts.is_multi_rat,
                        ],
                    ),
                ]):

            self.operation_details["Timeout"] += 288 + self.restrictions.\
                use_restrictions_from_OM_GEN_SFS_PERF_CAP_13441(
                admin_ru_id=self.admin_ru_id,
                init_ru_id=self.init_ru_id,
            )
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.13785"

        else:
            return super(ResetRf22R1, self).get_kpi()

        return self.operation_details
